mapper.select:
SELECT t.ticket_id, t.tenant_id, t.customer_id, t.customer_name, t.ticket_no, t.ticket_title, t.severity, t.issue_type, t.owner_id, t.owner_name, t.opened_time, t.resolved_time, t.due_time, t.description, t.solution, t.attachment_url, t.status, t.del_flag, t.create_by, t.create_time, t.update_by, t.update_time, c.dept_id AS scope_dept_id, c.owner_id AS scope_owner_id FROM oa_crm_service_ticket t INNER JOIN oa_crm_customer c ON c.customer_id = t.customer_id AND c.del_flag = '0' WHERE t.del_flag = '0'
AND t.customer_id = #{query.customerId}
AND t.ticket_title LIKE CONCAT('%', #{query.ticketTitle}, '%')
AND t.severity = #{query.severity}
AND t.status = #{query.status}
ORDER BY t.update_time DESC
